<template>
  <template v-for="(seg, i) in segments" :key="i">
    <ChatsLinkifiedTextLink
      v-if="seg.type === 'link'"
      :seg="seg"
      :link-color-class="linkColorClass"
      :link-active-bg-class="linkActiveBgClass"
      :is-mobile="isMobile"
    />
    <template v-else>{{ seg.value }}</template>
  </template>
</template>

<script setup lang="ts">
import ChatsLinkifiedTextLink from '@/components/chats/ChatsLinkifiedTextLink.vue';
import { linkifyTokens } from '@/utils/linkifyTokens';

interface Props {
  text: string | null | undefined;
  variant?: 'sent' | 'received';
}

const props = withDefaults(defineProps<Props>(), { variant: 'received' });

const segments = computed(() => linkifyTokens(props.text));

const linkColorClass = computed(() => (props.variant === 'sent' ? 'text-white' : 'text-primary'));

const linkActiveBgClass = computed(() => (props.variant === 'sent' ? 'bg-white/25' : 'bg-primary/20'));

const { isMobile } = useMobileForWeb();
</script>
