import { withSupabase } from './useCheckSupabaseClient';

export const useUploadFileFunc = (path: string, file: File) => {
  return withSupabase((supabase) =>
    supabase.storage.from('attachments').upload(path, file, {
      contentType: file.type || 'application/octet-stream',
      upsert: false,
    })
  );
};

export type UploadFileResponse = Awaited<ReturnType<typeof useUploadFileFunc>>;
