import { withSupabase } from './useCheckSupabaseClient';
import type { PendingAttachment } from '~/types/attachments';

export type UploadAttachmentsArgs = {
  chatId: string;
  senderId: string;
  groupId: string;
  uploaded: PendingAttachment[];
};

export const useUploadAttachmentsFunc = (args: UploadAttachmentsArgs) => {
  //TODO: rewrite using funcitons
  const payload = args.uploaded.map((item) => ({
    sender_id: args.senderId,
    channel_id: args.chatId,
    group_id: args.groupId,
    bucket: item.bucket,
    path: item.path,
    name: item.name,
    mime: item.mime,
    size: item.size,
    width: item.width,
    height: item.height,
    duration_ms: item.duration_ms,
    meta: item.meta ?? {},
  }));
  return withSupabase((supabase) => supabase.from('attachments').insert(payload));
};

export type UploadAttachmentsResponse = Awaited<ReturnType<typeof useUploadAttachmentsFunc>>;
