import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

export type MuteChatArgs = Database['private']['CompositeTypes']['mute_chat_input'];

export const useMuteChatFunc = async (data: MuteChatArgs) => {
  return withSupabase((supabase) =>
    supabase.rpc('mute_chat', {
      input: {
        chat_id: data.chat_id,
      },
    })
  );
};

export type MuteChatResponse = Awaited<ReturnType<typeof useMuteChatFunc>>;
