import type { PostgrestSingleResponse } from '@supabase/supabase-js';
import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

type GetChatMessagesArgs = Database['private']['CompositeTypes']['get_messages_with_details_input'];
type GetChatMessagesAtArgs = Database['private']['CompositeTypes']['get_messages_at_with_details_input'];

export const useChatMessages = async (args: GetChatMessagesArgs) => {
  return withSupabase((supabase) => supabase.rpc('get_messages_with_details', { input: args }));
};

export const useChatMessagesAt = async (args: GetChatMessagesAtArgs) => {
  return withSupabase((supabase) => supabase.rpc('get_messages_at_with_details', { input: args }));
};

export type ChatMessage = Database['private']['Functions']['get_messages_with_details']['Returns'][number];
export type SystemMessageMetadata = Database['private']['CompositeTypes']['system_message_metadata'];
export type ChatParticypantMessageBody = Database['private']['CompositeTypes']['system_message_new_participant'];
export type UserMessageMetadata = Database['private']['CompositeTypes']['user_message_metadata'];
export type UserMessageWithAttachments = Database['private']['CompositeTypes']['user_message_with_attachments'];
export type GetMessagesResponse = PostgrestSingleResponse<ChatMessage[]>;

export type Timeline = {
  items: ChatMessage[];
  error: any;
  oldestId: number | null;
  newestId: number | null;
  hasOlder: boolean;
  hasNewer: boolean;
};
