import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

type GetChannelDetailsArgs = Database['private']['CompositeTypes']['get_chat_info_input'];

export const useGetChannelDetails = async (data: GetChannelDetailsArgs) => {
  return withSupabase((supabase) => supabase.schema('private').rpc('get_chat_info', { input: data }));
};

export type GetChannelDetailsResponse = Awaited<ReturnType<typeof useGetChannelDetails>>;
