<template>
  <div
    :id="message.id!.toString()"
    :class="
      cn('w-full flex p-1 rounded-md', isUserMessage && !channelChatType ? 'justify-end' : 'justify-start', {
        'justify-center p-0': message.type === 'SYSTEM',
        'bg-blue-50': editingMessageId === message.id,
        'message-highlight': highlighted,
      })
    "
    @click.stop="
      async (e) => {
        if (message.type === 'USER') await messageContextMenuTrigger(message, { x: e.clientX, y: e.clientY });
      }
    "
  >
    <div
      v-if="message.type === 'USER'"
      :class="cn('flex flex-col gap-1 w-fit', isUserMessage && !channelChatType ? 'flex-row-reverse' : 'flex-row')"
    >
      <component
        :is="chatWithGrace ? ChatGraceInfoModal : ChatUserInfoModal"
        :id="message.sender_id"
        @click="async () => await messageContextMenuTrigger(null, null)"
      >
        <ChatsUserAvatar
          :avatar-url="message.sender_avatar_url"
          :name="message.sender_display_name"
          size="xs"
          class="cursor-pointer"
          @click.stop
        />
      </component>
      <div
        ref="userMessageWrapper"
        :class="
          cn(
            'flex flex-col justify-between',
            isSentBubble
              ? 'bg-blue-500 text-white rounded-2xl rounded-br-sm px-3 py-1.5'
              : 'bg-gray-100 text-gray-900 rounded-2xl rounded-bl-sm px-3 py-1.5',
            {
              'pt-2': !message.sender_display_name && message.reply_to_message_id,
            }
          )
        "
        @click.stop="async (e) => await messageContextMenuTrigger(message, { x: e.clientX, y: e.clientY })"
      >
        <div
          v-if="message.sender_display_name && channelChatType"
          :class="
            cn(
              'flex items-center justify-between w-full gap-2',
              isUserMessage && !channelChatType ? 'flex-row-reverse' : 'flex-row'
            )
          "
        >
          <p :class="cn('text-sm font-medium')">{{ message.sender_display_name }}</p>
        </div>
        <div
          v-if="message.reply_to_message_id"
          :class="
            cn(
              'border-l-2 p-1 pl-2 flex flex-col rounded-sm w-fit cursor-pointer select-none',
              isSentBubble
                ? 'bg-blue-400/30 border-blue-200 text-end self-end'
                : 'bg-blue-50 border-blue-600 text-start self-start'
            )
          "
          @click.stop.prevent="
            () => {
              if (!message.reply_to_message_deleted) {
                $emit('go-to-reply-trigger', message.reply_to_message_id!);
              }
            }
          "
        >
          <p v-if="message.reply_to_message_deleted" class="text-xs text-destructive flex items-center gap-1">
            <Trash2Icon class="w-4 h-4" /> <span>Message deleted</span>
          </p>
          <template v-else>
            <div class="flex gap-2 items-center">
              <Spinner v-if="isGoingToRepliedMessage" class="w-4 h-4" />
              <p
                v-if="message.reply_to_message_sender_display_name"
                :class="cn('w-full text-xs', isSentBubble ? 'text-blue-100' : 'text-blue-500')"
              >
                {{ message.reply_to_message_sender_display_name }}
              </p>
            </div>
            <p
              v-if="message.reply_to_message_preview"
              :class="
                cn(
                  'text-xs line-clamp-2 whitespace-pre-wrap [overflow-wrap:anywhere]',
                  isSentBubble ? 'text-blue-100' : 'text-accent-foreground'
                )
              "
            >
              {{ message.reply_to_message_preview }}
            </p>
            <p
              v-else-if="
                Array.isArray(message.reply_to_message_attachments) &&
                message.reply_to_message_attachments.length &&
                isAttachment(message.reply_to_message_attachments[0])
              "
              :class="
                cn(
                  'flex items-center gap-1 text-xs',
                  isSentBubble ? 'text-blue-100' : 'text-accent-foreground',
                  isUserMessage && !channelChatType ? 'justify-end' : 'justify-start'
                )
              "
            >
              <FileIcon class="w-4 h-4" />
              <span>{{ message.reply_to_message_attachments[0]?.name }}</span>
              <span v-if="message.reply_to_message_attachments.length >= 2"
                >+ {{ message.reply_to_message_attachments.length - 1 }} more</span
              >
            </p>
          </template>
        </div>
        <div
          v-if="Array.isArray(message.attachments) && message.attachments.length"
          :class="
            cn(
              'mt-2 flex flex-wrap gap-2',
              isUserMessage && !channelChatType ? 'justify-end' : 'justify-start',
              'max-w-[calc(2*6rem+1*0.5rem)] sm:max-w-[calc(3*6rem+2*0.5rem)] lg:max-w-[calc(4*6rem+3*0.5rem)]'
            )
          "
        >
          <template v-for="attachment in message.attachments">
            <ChatAttachmentItem
              v-if="isAttachment(attachment)"
              :key="attachment.id"
              :attachment="attachment"
              enable-download
              upload-status="success"
              class="shrink-0"
            />
          </template>
        </div>
        <span
          :class="
            cn(
              'text-sm whitespace-pre-wrap [overflow-wrap:anywhere]',
              isSentBubble ? 'text-white' : 'text-accent-foreground',
              isUserMessage && !channelChatType ? 'text-end' : 'text-start'
            )
          "
        >
          <ChatsLinkifiedText :text="message.body" :variant="isSentBubble ? 'sent' : 'received'" />
        </span>
        <div
          :class="
            cn(
              'flex items-center gap-1 justify-between',
              isUserMessage && !channelChatType ? 'flex-row' : 'flex-row-reverse'
            )
          "
        >
          <div class="flex gap-1">
            <template v-if="isUserMessage">
              <CheckCheckIcon
                v-if="isUsersMessageRead"
                :class="cn('w-4 h-4', isSentBubble ? 'text-white' : 'text-accent2-foreground')"
              />
              <CheckIcon v-else :class="cn('w-4 h-4', isSentBubble ? 'text-blue-200' : 'text-muted-foreground')" />
            </template>
            <span
              v-if="message.created_at"
              :class="cn('text-xs', isSentBubble ? 'text-blue-100' : 'text-muted-foreground')"
              >{{ messageTime }}</span
            >
          </div>
          <span
            v-if="message.edited_at"
            :class="cn('text-xs', isSentBubble ? 'text-blue-200' : 'text-muted-foreground')"
            >edited</span
          >
        </div>
      </div>
    </div>
    <div v-else-if="message.type === 'SYSTEM' && isSystemMessageMetadata(message.metadata)">
      <div
        v-if="isChatParticipantSystemMessage(message.metadata.event_body)"
        class="text-xs text-muted-foreground whitespace-pre-wrap [overflow-wrap:anywhere]"
      >
        {{ newParticipantmessageProcess(message.metadata.event_body) }}
      </div>
      <div
        v-else-if="isChatCreationSystemMessage(message.metadata.event_body)"
        class="text-xs text-muted-foreground whitespace-pre-wrap [overflow-wrap:anywhere]"
      >
        Chat created
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { cn } from '@/lib/utils';
import type {
  ChatMessage,
  SystemMessageMetadata,
  ChatParticypantMessageBody,
} from '@/composables/supabase/useChatMessages';
import type { GetChatInfoResponse, ChatType } from '~/composables/supabase/useChatInfo';
import { CheckIcon, CheckCheckIcon, FileIcon, Trash2Icon } from 'lucide-vue-next';
import ChatUserInfoModal from '@/components/chats/ChatUserInfoModal.vue';
import ChatGraceInfoModal from '@/components/chats/ChatGraceInfoModal.vue';
import Spinner from '~/assets/icons/spinner.svg';
import { GRACE_ID } from '~/constants/chats/graceId';

interface Props {
  message: ChatMessage;
  lastReadMessageId?: number | null;
  lastUsersReadMessageId?: number | null;
  chatInfoData?: GetChatInfoResponse | undefined;
  chatType?: ChatType | null;
  editingMessageId?: number | null;
  highlighted?: boolean;
  isGoingToRepliedMessage: boolean;
}

const props = defineProps<Props>();

interface Emits {
  (e: 'go-to-reply-trigger', messageId: number): void;
}

defineEmits<Emits>();

const { userId, timezone } = useUserRole();

const isUserMessage = computed(() => props.message.sender_id === userId.value);

const channelChatType = computed(() => props.chatType === 'CHANNEL');

const isSentBubble = computed(() => isUserMessage.value && !channelChatType.value);

const chatWithGrace = computed(
  () => props.chatInfoData?.data?.dm_with_user_id === GRACE_ID && props.chatInfoData?.data?.type === 'DM'
);

const isUsersMessageRead = computed(
  () => props.message.id && props.lastUsersReadMessageId && props.message.id <= props.lastUsersReadMessageId
);

function isSystemMessageMetadata(metadata: unknown): metadata is SystemMessageMetadata {
  return props.message.type === 'SYSTEM';
}

function isChatParticipantSystemMessage(eventBody: unknown): eventBody is ChatParticypantMessageBody {
  return isSystemMessageMetadata(props.message.metadata) && props.message.metadata.event_type === 'new_participant';
}

function isChatCreationSystemMessage(eventBody: unknown): eventBody is ChatParticypantMessageBody {
  return isSystemMessageMetadata(props.message.metadata) && props.message.metadata.event_type === 'chat_created';
}

function newParticipantmessageProcess(body: ChatParticypantMessageBody) {
  if (body.user_id === userId.value) return 'You were added to the chat';
  else return `User ${body.display_name} was added to the chat`;
}

function isAttachment(attachment: unknown): attachment is PendingAttachment {
  return typeof attachment === 'object' && attachment !== null && 'id' in attachment && 'path' in attachment;
}

const messageContextMenuTrigger = inject('messageContextMenuTrigger') as (
  message: ChatMessage | null,
  pointer: { x: number; y: number } | null
) => Promise<void>;

const userMessageWrapper = useTemplateRef('userMessageWrapper');

onClickOutside(userMessageWrapper, async () => {
  await messageContextMenuTrigger(null, null);
});

const messageTime = computed(() => {
  if (!props.message.created_at || !timezone.value) return null;
  return formatDateTzToFormat(props.message.created_at, 'hh:mm a', timezone.value)?.toLowerCase();
});
</script>

<style scoped>
@keyframes message-highlight-fade {
  0% {
    background-color: rgb(219 234 254);
  }
  100% {
    background-color: transparent;
  }
}

.message-highlight {
  animation: message-highlight-fade 5s ease forwards;
}
</style>
