        ref="scrollEl"
        class="relative flex-1 min-h-0 overflow-y-auto p-2"
        @vue:mounted="onScrollElMount"
        @vue:before-unmount="onScrollElUnmount"
      >
        <div class="min-h-full flex flex-col justify-end gap-2">
          <ChatCornerElement ref="topEl" @vue:mounted="onTopElMount" @vue:before-mount="onTopElUnmount" />
          <template
            v-for="(entry, idx) in groupedItems"
            :key="entry.type === 'message' ? entry.message.id! : `sep-${idx}`"
          >
            <div v-if="entry.type === 'separator'" class="flex items-center justify-center my-2">
              <span class="text-xs text-muted-foreground bg-background px-3 py-0.5 rounded-full border">
                {{ entry.date }}
              </span>
            </div>
            <ChatsMessage
              v-else
              ref="messagesEls"
              :message="entry.message"
              :last-read-message-id="lastReadMessageId"
              :last-users-read-message-id="lastUsersReadMessageId"
              :chat-type="chatInfoData?.data?.type"
              :chat-info-data="chatInfoData"
              :editing-message-id="editingMessageId"
              :highlighted="highlightedMessageId === entry.message.id"
              :is-going-to-replied-message="isGoingToRepliedMessage === entry.message.id"
              @go-to-reply-trigger="goToRepliedMessage"
              @vue:mounted="(el) => onMessageMount(el)"
              @vue:unmounted="(el) => onMessageUnmount(el)"
            />
          </template>
          <ChatCornerElement ref="bottomEl" @vue:mounted="onBottomElMount" @vue:unmounted="onBottomElUnmount" />
        </div>
        <div v-if="isScrollToBottom" class="sticky bottom-2 ml-auto left-full z-10 w-fit">
          <Button variant="outline" size="icon" class="rounded-full relative" @click.stop.prevent="goToNewest">
            <Badge
              v-if="isNewMessageBadge"
              variant="info"
              class="h-4 min-w-4 rounded-full px-1 absolute -top-1 -left-1"
            />
            <Spinner v-if="isGoingToBottom" />
            <ArrowDownIcon v-else />
          </Button>
        </div>
      </ChatMainScrollWrapper>
      <div
        v-if="isLinkMenuOverlayShown"
        class="absolute inset-0 z-40"
        @pointerdown.stop.prevent="onLinkMenuOverlayDown"
        @pointerup.stop.prevent="onLinkMenuOverlayUp"
        @pointercancel="onLinkMenuOverlayCancel"
        @click.stop.prevent
        @contextmenu.stop.prevent
      />
    </div>
    <slot name="inputs" />
  </template>
</template>
<script setup lang="ts">
import type { ChatMessage, Timeline } from '~/composables/supabase/useChatMessages';
import { useChatMessages, useChatMessagesAt } from '~/composables/supabase/useChatMessages';
import { ArrowDownIcon } from 'lucide-vue-next';
import type { VNode } from 'vue';
import ChatsMessage from './ChatsMessage.vue';
import { useMarkMessageAsRead } from '~/mutations/chats/markMessageAsRead';
import { servingOffline } from '~/utils/offlineCache';
import { Spinner } from '~/assets/icons';
import ChatMainScrollWrapper from './ChatMainScrollWrapper.vue';
import type { GetChatInfoResponse } from '~/composables/supabase/useChatInfo';

interface Props {
  chatId?: string | null;
  limit?: number;
  loading?: boolean;
  data?: Timeline;
  loadingSubject?: string;
  lastMessageIdInView?: number | null;
  lastReadMessageId?: number | null;
  lastMessageInChat?: { id: number | null; userId: string | null } | null;
  lastUsersReadMessageId?: number | null;
  chatInfoData?: GetChatInfoResponse | undefined;
  editingMessageId?: number | null;
}
const props = withDefaults(defineProps<Props>(), {
  chatId: null,
  limit: 50,
  loading: false,
  data: () => ({
    items: [],
    error: null,
    oldestId: null,
    newestId: null,
    hasOlder: true,
    hasNewer: true,
  }),
  loadingSubject: 'chat data',
  lastMessageIdInView: undefined,
  lastReadMessageId: undefined,
  lastMessageInChat: undefined,
  lastUsersReadMessageId: undefined,
  chatInfoData: undefined,
  editingMessageId: undefined,
});

const scrollEl = useTemplateRef('scrollEl');
const topEl = useTemplateRef('topEl');
const bottomEl = useTemplateRef('bottomEl');
const messagesEls = ref<InstanceType<typeof ChatsMessage>[]>([]);

const isScrollToBottom = ref<boolean>(false);

function isNearBottom(el: HTMLElement | undefined, px = 120) {
  if (!el) return false;
  return el.scrollHeight - (el.scrollTop + el.clientHeight) <= px;
}

async function scrollToBottom(behavior: ScrollBehavior = 'auto') {
  await nextTick();
  bottomEl.value?.$el.scrollIntoView({ block: 'center', behavior });
}

function captureAnchor() {
  const el = scrollEl.value?.$el;
  if (!el) return null;

  return {
    scrollTop: el.scrollTop,
    scrollHeight: el.scrollHeight,
    nearBottom: isNearBottom(el),
  };
}

function restoreAnchor(before: ReturnType<typeof captureAnchor>, type: 'new' | 'old') {
  const el = scrollEl.value?.$el;
  if (!el || !before) return;

  const delta = el.scrollHeight - before.scrollHeight;

  if (type === 'new') el.scrollTop = before.scrollTop;
  if (type === 'old') el.scrollTop = before.scrollTop + delta;
}
