async function onScrollElMount() {
  // if (!props.lastMessageIdInView) await scrollToBottom(); //TODO add opacity or something that will hide scroll process to correct message
  await nextTick();
  await nextFrame();
  await nextFrame();
  const lastMessage = messagesEls.value?.at(-1);
  if (!props.lastReadMessageId) {
    // if we have no read messages, scroll to last message in chat, not to last message in view
    console.warn('No lastReadMessageId, scrolling to last message in chat');
    lastMessage?.$el.scrollIntoView({ behavior: 'auto', block: 'end', container: 'nearest' });
  } else if (!lastMessage?.$props?.message.sender_id) {
    // channels doesn't have sender_id in messages, so we scroll to last read message if it's channel, not to last message in chat
    console.warn('No sender_id in message, probably channel, scrolling to last read message');
    const lastMessageId = props.chatInfoData?.data?.last_read_message_id;
    const lastMessage = messagesEls.value?.find((el) => Number(el?.$props?.message.id) === lastMessageId);
    lastMessage?.$el.scrollIntoView({ behavior: 'auto', block: 'end', container: 'nearest' });
  } else if (lastMessage?.$props?.message.sender_id === userId.value) {
    // if last message is sent by user, scroll to it
    console.warn('Last message is sent by user, scrolling to it');
    lastMessage?.$el.scrollIntoView({ behavior: 'auto', block: 'end', container: 'nearest' });
  } else if (props.lastReadMessageId) {
    // in other cases scroll to last read message
    console.warn('Scrolling to last read message');
    const messageScrollTo = messagesEls.value?.find((el) => Number(el?.$el?.id) === props.lastReadMessageId);
    await messageScrollTo?.$el?.scrollIntoView({ behavior: 'auto', block: 'end', container: 'nearest' });
    isScrollToBottom.value = !isNearBottom(scrollEl.value?.$el, 300);
  }
  // if (scrollEl.value?.$el) setupScrollResizeStabilizer(scrollEl.value?.$el); //TODO test after enabling, may broke chat opening logic

  //if we have all messages on screen on chat page load (no scroll), mark last message as read instantly

  const scrollHTMLElement = scrollEl.value?.$el as HTMLElement | undefined;
  const lastElementId = props.data.items.at(-1)?.id;
  if (
    scrollHTMLElement?.scrollHeight &&
    scrollHTMLElement?.clientHeight &&
    scrollHTMLElement?.scrollHeight === scrollHTMLElement?.clientHeight &&
    lastElementId &&
    props.chatInfoData?.data?.last_message_id &&
    (!props.lastReadMessageId || Number(props.lastReadMessageId) < Number(props.chatInfoData.data.last_message_id))
  ) {
    highestVisibleId.value = Number(props.chatInfoData.data.last_message_id);
    if (!servingOffline.value) {
      markMessageAsRead({
        chat_id: props.chatId,
        message_id: lastElementId,
      });
    }
  }
}

async function onScrollElUnmount() {
  // if (scrollResizeObserver.value && scrollEl.value) scrollResizeObserver.value.unobserve(scrollEl.value.$el);
