const cache = useQueryCache();

function patchTimeline(updater: (prev: Timeline) => Timeline) {
  cache.setQueryData(['messages.id', props.chatId], (prev?: Timeline) => {
    const base: Timeline = prev ?? {
      items: [],
      error: null,
      oldestId: null,
      newestId: null,
      hasOlder: true,
      hasNewer: true,
    };
    return updater(base);
  });
}

async function loadDataBatch(type: 'new' | 'old') {
  try {
    if (!props.data?.hasOlder && type === 'old') return;
    if (!props.data?.hasNewer && type === 'new') return;
    if (props.data.items.length < props.limit) return;
    await nextTick();
    await nextFrame();
    await nextFrame();
    const before = captureAnchor();

    const res = await useChatMessages({
      chat_id: props.chatId,
      before_message_id: type === 'old' ? props.data?.oldestId || null : null,
      after_message_id: type === 'new' ? props.data?.newestId || null : null,
      message_limit: props.limit,
    });

    if (res?.error) {
      captureExceptionToSentry(new Error('Failed to get chat messages batch: ' + res.error.message));
    }

    const batch = dedupeAsc<ChatMessage>(res.data ?? []);
    if (!batch.length) {
      patchTimeline((prev) => ({ ...prev, error: null, hasOlder: false }));
      return;
    }

    patchTimeline((prev) => {
      const list = type === 'old' ? [...batch, ...(prev.items ?? [])] : [...(prev.items ?? []), ...batch];
      const items = dedupeAsc<ChatMessage>(list);
      return {
        ...prev,
        items,
        error: res.error,
        oldestId: items[0]?.id ?? null,
        newestId: items.at(-1)?.id ?? null,
        hasOlder: type === 'old' ? batch.length === props.limit : prev.hasOlder,
        hasNewer:
          type === 'new'
            ? items.at(-1)?.id != null &&
              props.chatInfoData?.data?.last_message_id != null &&
              Number(items.at(-1)?.id) < Number(props.chatInfoData.data.last_message_id)
            : prev.hasNewer,
      };
    });

    await nextTick();
    restoreAnchor(before, type);
  } catch (err) {
    console.error('Failed to load data batch', err);
  }
}

const topElObserver = ref<IntersectionObserver | null>(null);

async function onTopElMount() {
  console.log('onTopElMount');
  if (topElObserver.value) return;
  topElObserver.value = new IntersectionObserver(
    (entries) => {
      if (entries[0]?.isIntersecting) loadDataBatch('old');
    },
    { rootMargin: '300px', root: scrollEl.value?.$el ?? null }
  );
  topElObserver.value.observe(topEl.value!.$el);
}

function onTopElUnmount() {
  topElObserver.value?.disconnect();
  topElObserver.value = null;
}

const bottomElObserver = ref<IntersectionObserver | null>(null);

async function onBottomElMount() {
  console.log('onBottomElMount');
  if (bottomElObserver.value) return;
  bottomElObserver.value = new IntersectionObserver(
    (entries) => {
      if (entries[0]?.isIntersecting) {
        loadDataBatch('new');
        isScrollToBottom.value = props.data.items.at(-1)?.id !== props.lastMessageInChat?.id;
      } else {
        isScrollToBottom.value = !isNearBottom(scrollEl.value?.$el, 300);
      }
    },
    { rootMargin: '300px', root: scrollEl.value?.$el ?? null }
  );
  bottomElObserver.value.observe(bottomEl.value!.$el);
}

function onBottomElUnmount() {
  bottomElObserver.value?.disconnect();
  bottomElObserver.value = null;
}

const messagesObserver = ref<IntersectionObserver | null>(null);

const { markMessageAsRead } = useMarkMessageAsRead();

const highestVisibleId = ref<number | null>(null);

const sendReadUpdate = useThrottleFn(
  (element: Element) => {
    if (!highestVisibleId.value || servingOffline.value) return;

    markMessageAsRead({
      chat_id: props.chatId,
      message_id: highestVisibleId.value,
    }).then(() => {
      messagesObserver.value?.unobserve(element);
    });
  },
  1000,
  true,
  true
);

function createMessageObserver() {
  return new IntersectionObserver(
    (entries) => {
      for (const el of entries) {
        if (el.isIntersecting) {
          const id = Number(el.target.id);
          if (!highestVisibleId.value || id > highestVisibleId.value) {
            highestVisibleId.value = id;
            sendReadUpdate(el.target);
          }
        }
      }
    },
    {
      root: scrollEl.value?.$el ?? null,
      threshold: 0.6,
    }
  );
}

const { userId, timezone } = useUserRole();

const groupedItems = computed(() => {
  const result: Array<{ type: 'separator'; date: string } | { type: 'message'; message: ChatMessage }> = [];
  let lastDateKey: string | null = null;

  for (const m of props.data.items) {
    if (!m.created_at) {
      result.push({ type: 'message', message: m });
      continue;
    }
    const dateKey = formatDateTzToFormat(m.created_at, 'yyyy-MM-dd', timezone.value);
    if (dateKey && dateKey !== lastDateKey) {
      lastDateKey = dateKey;
      const isToday = isSameZonedDayAsToday(m.created_at, timezone.value!);
      const label = isToday ? 'Today' : formatDateTzToFormat(m.created_at, 'MMMM d, yyyy', timezone.value);
      result.push({ type: 'separator', date: label ?? dateKey });
    }
    result.push({ type: 'message', message: m });
  }
  return result;
});

function onMessageMount(messageEl: VNode) {
  if (!messageEl) return;
  const messageData: ChatMessage | undefined = messageEl.props?.message;
  const element: HTMLElement | null = messageEl.el as HTMLElement | null;
  if (!messagesObserver.value) messagesObserver.value = createMessageObserver();
  if (
    element &&
    messageData?.sender_id !== userId.value &&
    messageData?.id &&
    (!props.lastReadMessageId || messageData?.id > props.lastReadMessageId)
  ) {
    messagesObserver.value?.observe(element);
  }
}

function onMessageUnmount(messageEl: VNode) {
  if (!messageEl) return;

  const element: HTMLElement | null = messageEl.el as HTMLElement | null;
  if (element) messagesObserver.value?.unobserve(element);
}

onUnmounted(() => {
  messagesObserver.value?.disconnect();
  messagesObserver.value = null;
  highestVisibleId.value = null;
});

const isProgrammaticScroll = ref<boolean>(false);

function nextFrame() {
  return new Promise<void>((r) => requestAnimationFrame(() => r()));
}

async function onSendMessage(message: ChatMessage) {
  const isNearBottomSnap = isNearBottom(scrollEl.value?.$el);
  if (isNearBottomSnap) isProgrammaticScroll.value = true;
  patchTimeline((prev) => {
    const items = dedupeAsc<ChatMessage>([...(prev.items ?? []), message]);
    return {
      ...prev,
      items,
      oldestId: items[0]?.id ?? null,
      newestId: items.at(-1)?.id ?? null,
    };
  });
  await nextTick();
  await nextFrame();
  await nextFrame();
  if (scrollEl.value && isNearBottomSnap) {
    if (!!message.sender_id || userId.value === message.sender_id) {
      scrollEl.value?.$el.scrollTo({ top: scrollEl.value?.$el.scrollHeight, behavior: 'smooth' });
    } else {
      messagesEls.value?.at(-1)?.$el?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    await nextFrame();
  }
  isProgrammaticScroll.value = false;
}

const isGoingToBottom = ref<boolean>(false);

async function goToNewest() {
  isGoingToBottom.value = true;
  const isLastMessageLoaded = props.data.items.find((message) => message.id === props.lastMessageInChat?.id);
  if (isLastMessageLoaded) await scrollToBottom('auto');
  else {
    const res = await useChatMessages({
      chat_id: props.chatId,
      message_limit: props.limit,
      after_message_id: null,
      before_message_id: null,
    });
    if (res.error) {
      console.error('Failed to load new messages', res.error);
      showToastError('Please try to reload the page', 'Failed to load new messages');
      captureExceptionToSentry(new Error('Failed to load new messages on goToNewest click: ' + res.error.message));
      return;
    }
    if (res.data) {
      patchTimeline(() => {
        const items = res.data;

        return {
          items,
          error: res.error,
          oldestId: items[0]?.id ?? null,
          newestId: items.at(-1)?.id ?? null,
          hasOlder: (res?.data?.length ?? 0) === props.limit,
          hasNewer:
            items.at(-1)?.id != null &&
            props.chatInfoData?.data?.last_message_id != null &&
            Number(items.at(-1)?.id) < Number(props.chatInfoData.data.last_message_id),
        };
      });
    }
    await scrollToBottom();
  }
  isGoingToBottom.value = false;
}

const isNewMessageBadge = computed(
  () =>
    props.lastMessageInChat?.userId !== userId.value &&
    (props.lastMessageInChat?.id ?? 0) > (props.lastReadMessageId ?? 0)
);

defineExpose({
  onSendMessage,
});

const isAbsorbingLinkMenuTap = ref(false);
const isLinkMenuOverlayShown = computed(() => isAnyLinkMenuOpen.value || isAbsorbingLinkMenuTap.value);

function onLinkMenuOverlayDown() {
  isAbsorbingLinkMenuTap.value = true;
  linkMenuCloseSignal.value++;

  // Drag-off safety net: if the user releases the pointer off the overlay, the local
  // @pointerup won't fire and the overlay would stay stuck blocking taps. Listen at
  // window level so any pointerup/cancel for this gesture clears the flag.
  const onWindowEnd = () => {
    isAbsorbingLinkMenuTap.value = false;
    window.removeEventListener('pointerup', onWindowEnd);
    window.removeEventListener('pointercancel', onWindowEnd);
  };
  window.addEventListener('pointerup', onWindowEnd);
  window.addEventListener('pointercancel', onWindowEnd);
}

// Defer to the next macrotask so the `click` event (fired after `pointerup`) still
// lands on the mounted overlay and is absorbed by `@click.stop.prevent`. Without this
// defer the overlay unmounts between `pointerup` and `click`, and the click bubbles
// through to the message underneath, opening its context menu.
function onLinkMenuOverlayUp() {
  setTimeout(() => {
    isAbsorbingLinkMenuTap.value = false;
  }, 0);
}

function onLinkMenuOverlayCancel() {
  isAbsorbingLinkMenuTap.value = false;
}

const highlightedMessageId = ref<number | null>(null);

function triggerHighlight(id: number) {
  highlightedMessageId.value = id;

  setTimeout(() => {
    if (highlightedMessageId.value === id) {
      highlightedMessageId.value = null;
    }
  }, 4000);
}

const isGoingToRepliedMessage = ref<number | null>(null);

async function goToRepliedMessage(messageId: number) {
  const messageEl = messagesEls.value?.find((el) => el?.$props?.message?.id === messageId);
  if (messageEl) {
    messageEl?.$el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    triggerHighlight(messageId);
  } else {
    isGoingToRepliedMessage.value = messageId;
    const res = await useChatMessagesAt({
      chat_id: props.chatId,
      at_message_id: messageId,
      message_limit: props.limit,
    });
    if (res.error) {
      console.error('Failed to load messages at id', res.error);
      showToastError('Failed to load replied message');
      captureExceptionToSentry(
        new Error('Failed to get chat messages at id ' + messageId + ' on reply navigation: ' + res.error.message)
      );
      return;
    }
    if (res.data) {
      patchTimeline(() => {
        const items = res.data;

        return {
          items,
          error: res.error,
          oldestId: items[0]?.id ?? null,
          newestId: items.at(-1)?.id ?? null,
          hasOlder: (res?.data?.length ?? 0) === props.limit,
          hasNewer:
            items.at(-1)?.id != null &&
            props.chatInfoData?.data?.last_message_id != null &&
            Number(items.at(-1)?.id) < Number(props.chatInfoData.data.last_message_id),
        };
      });
      await nextTick();
      isGoingToRepliedMessage.value = null;
      const messageEl = messagesEls.value?.find((el) => el?.$props?.message?.id === messageId);
      messageEl?.$el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      triggerHighlight(messageId);
    }
  }
}
</script>
