<template>
  <div class="rounded-md min-w-24 min-h-24 w-24 h-24 relative z-0 overflow-hidden cursor-pointer">
    <template v-if="uploadStatus === uploadStatuses.queued || uploadStatus === uploadStatuses.uploading">
      <div class="absolute z-20 bg-slate-500 opacity-60 w-full h-full" />
      <div class="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-30">
        <Spinner class="w-6 h-6" />
      </div>
    </template>
    <template v-if="uploadStatus === uploadStatuses.error">
      <div class="absolute z-20 bg-red-200 opacity-60 w-full h-full" />
      <div class="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-30">
        <RotateCcwIcon
          v-if="enableRetry"
          class="w-7 h-7 stroke-destructive cursor-pointer"
          @click.stop.prevent="retryUpload(attachment.id)"
        />
        <AlertCircleIcon v-else class="w-7 h-7 stroke-destructive" />
      </div>
    </template>

    <ChatAttachmentPreview
      :attachment="attachment"
      :preview-url="previewUrl"
      :file-extension="fileExtension"
      :download-enabled="enableDownload"
    />
    <button
      v-if="isRemovable"
      class="absolute right-1.5 top-1.5 px-0 bg-slate-500/70 duration-300 rounded-md z-40"
      :variant="null"
      size="sm"
      @click.stop.prevent="removeAttachment(attachment.id)"
    >
      <XIcon class="w-4 h-4 stroke-slate-100 hover:stroke-slate-800" />
    </button>
  </div>
</template>

<script setup lang="ts">
import { uploadStatuses } from '~/constants/chats/attachments';
import { Spinner } from '~/assets/icons';
import { XIcon, RotateCcwIcon, AlertCircleIcon } from 'lucide-vue-next';

interface Props {
  attachment: PendingAttachment;
  isRemovable?: boolean;
  enableRetry?: boolean;
  previewUrl?: string | null;
  enableDownload?: boolean;
  uploadStatus?: UploadStatus;
  uploadError?: string | null;
  file?: File | null;
}

const props = withDefaults(defineProps<Props>(), {
  isRemovable: false,
  enableRetry: false,
  previewUrl: null,
  enableDownload: false,
  uploadStatus: undefined,
  uploadError: null,
  file: null,
});

interface Emits {
  (e: 'remove', id: string): void;

  (e: 'retry', id: string): void;
}

const emits = defineEmits<Emits>();

function retryUpload(id: string) {
  emits('retry', id);
}

function removeAttachment(id: string) {
  emits('remove', id);
}

const fileExtension = computed(() => props.attachment.name.split('.').pop()?.toLowerCase() || '');
</script>
