import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

export type MarkMessageAsReadArgs = Database['private']['CompositeTypes']['mark_message_read_input'];

export const useMarkMessageAsReadFunc = async (data: MarkMessageAsReadArgs) => {
  return withSupabase((supabase) =>
    supabase.rpc('mark_message_read', {
      input: {
        chat_id: data.chat_id,
        message_id: data.message_id,
      },
    })
  );
};

export type MarkMessageAsReadResponse = Awaited<ReturnType<typeof useMarkMessageAsReadFunc>>;
