import { updateFilePathFunc } from '~/composables/supabase/updateFilePath';

export const useUpdateFilePath = defineMutation(() => {
  const { mutateAsync: updateFilePath, asyncStatus } = useMutation({
    mutation: ({ oldPath, newPath }: { oldPath: string; newPath: string }) => {
      return updateFilePathFunc(oldPath, newPath);
    },
    onSuccess: (response) => {
      if (response.error) {
        console.error('Failed to update file path:', response.error);
        throw new Error('Failed to update file path');
      }
    },
    onError: (err) => {},
  });

  return {
    updateFilePath,
    isUpdatingFilePath: computed(() => asyncStatus.value === 'loading'),
  };
});
