import CardDescription from '~/components/ui/card/CardDescription.vue';
import { useUpdateFilePath } from '~/mutations/chats/updateFilePath';
import { useUploadAttachments } from '~/mutations/chats/uploadAttachments';
import { buildChatPath } from '~/utils/chats/processFiles';

export const useFileToChatProcessing = () => {
  type MoveOk = { ok: true; item: UploadItem; newPath: string };
  type MoveFail = { ok: false; item: UploadItem; newPath: string; error: string };

  const { updateFilePath } = useUpdateFilePath();
  const { uploadAttachments } = useUploadAttachments();

  function createMovingTasks(items: UploadItem[], chatId: string, groupId: string) {
    return items.map((item) => {
      const newPath = buildChatPath({
        chatId,
        filename: item.data.name,
        groupId,
        attachmentId: item.data.id,
      });

      const task = (async (): Promise<MoveOk> => {
        const res = await updateFilePath({ oldPath: item.data.path, newPath });

        if ((res as any)?.error) {
          throw (res as any).error;
        }

        return { ok: true, item, newPath };
      })();

      return { item, newPath, task };
    });
  }

  async function moveAttachments({
    chatId,
    files,
    userId,
    groupId,
  }: {
    chatId: string;
    files: UploadItem[];
    userId: string | null | undefined;
    groupId: string;
  }) {
    const wrapped = createMovingTasks(files, chatId, groupId); //TODO do something with files move error handling

    const settled = await Promise.allSettled(wrapped.map((w) => w.task));

    const moveResults: (MoveOk | MoveFail)[] = settled.map((s, idx) => {
      const { item, newPath } = wrapped[idx];

      if (s.status === 'fulfilled') {
        item.data.path = newPath;
        return { ok: true, item, newPath };
      } else {
        const msg = s.reason?.message ?? 'Move failed';
        return { ok: false, item, newPath, error: msg };
      }
    });
    const movedFail = moveResults.some((r) => !r.ok);
    if (movedFail) throw new Error('Failed to move some files');

    const movedOk = moveResults.filter((r): r is MoveOk => r.ok).map((r) => r.item);

    return movedOk.map((i) => i.data);
  }

  async function handleFiles({
    chatId,
    files,
    userId,
    groupId,
  }: {
    chatId: string;
    files: UploadItem[];
    userId: string | null | undefined;
    groupId: string;
  }) {
    if (!userId) throw new Error('Unknown user');

    const uploaded = files.some((file) => file.data.path.includes('draft-attachments'))
      ? await moveAttachments({ chatId, files, userId, groupId })
      : files.map((i) => i.data);

    const result = await uploadAttachments({
      chatId,
      senderId: userId,
      groupId,
      uploaded,
    });
    if (result.error) throw new Error('Failed to upload attachments');
  }

  return {
    handleFiles,
  };
};
