import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

export type SendMessageArgs = Database['private']['CompositeTypes']['send_message_input'];

export const useSendMessageFunc = async (data: SendMessageArgs) => {
  console.log('data', data);

  return withSupabase((supabase) =>
    supabase.rpc('send_message', {
      input: {
        chat_id: data.chat_id,
        body: data.body?.trim() ?? null,
        reply_to_message_id: data.reply_to_message_id,
        forwarded_from_user_id: data.forwarded_from_user_id,
        attachment_group_id: data.attachment_group_id?.toString() ?? null,
        dedup_key: data.dedup_key,
      },
    })
  );
};

export type SendMessageResponse = Awaited<ReturnType<typeof useSendMessageFunc>>;
