import { useMarkMessageAsReadFunc, type MarkMessageAsReadArgs } from '~/composables/supabase/useMarkMessageAsRead';
import type { GetChatInfoResponse } from '~/composables/supabase/useChatInfo';

export const useMarkMessageAsRead = defineMutation(() => {
  const { mutateAsync: markMessageAsRead, asyncStatus } = useMutation({
    mutation: (data: MarkMessageAsReadArgs) => useMarkMessageAsReadFunc(data),
    onSuccess: (data, params) => {
      if (data.error !== null) {
        console.error('Failed to mark message as read', data.error);
        if (data.status >= 300) {
          throw new Error('Failed to mark message as read');
        }
        return;
      }
      const queryCache = useQueryCache();
      queryCache.setQueryData<GetChatInfoResponse | undefined>(['chatInfo.id', params.chat_id], (prev) => {
        if (!prev) return prev;

        if (!prev.data) return prev;

        return {
          ...prev,
          data: {
            ...prev.data,
            last_read_message_id: params.message_id,
          },
        };
      });
    },
    onError: (err) => {
      console.error('Failed to mark message as read', err);
    },
  });

  return {
    markMessageAsRead,
    isMarkingMessageAsRead: computed(() => asyncStatus.value === 'loading'),
  };
});
