export function safeFilename(name: string) {
  return name.replaceAll('/', '_').replaceAll('\\', '_');
}

export function buildChatPath(args: ChatPathParams) {
  return `chat-attachments/${args.chatId}/${args.groupId}/${args.attachmentId}/${args.filename}`;
}

export function buildDraftPath(args: DraftPathParams) {
  return `draft-attachments/${args.userId}/${args.attachmentId}/${args.filename}`;
}

interface PathParams {
  attachmentId: string;
  filename: string;
}

interface DraftPathParams extends PathParams {
  userId: string;
}

interface ChatPathParams extends PathParams {
  chatId: string;
  groupId: string;
}

export function processFileData({
  file,
  chatId,
  groupId,
  bucket,
  userId,
  attachmentId,
}: {
  file: File;
  bucket: string;
  userId: string;
  chatId?: string | null;
  groupId?: string | null;
  attachmentId: string;
}): PendingAttachment {
  const filename = safeFilename(file.name);
  const path =
    chatId && groupId
      ? buildChatPath({ chatId, groupId, attachmentId, filename })
      : buildDraftPath({ userId, attachmentId, filename });
  //TODO: add handling for multiple files mime types
  return {
    id: attachmentId,
    bucket,
    path,
    name: filename,
    mime: file.type || null,
    size: file.size,
    width: null,
    height: null,
    duration_ms: null,
    meta: { source: 'upload' },
  };
}
