import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

type GetUserDetailsArgs = Database['private']['CompositeTypes']['get_user_info_input'];

export const useGetUserDetails = async (data: GetUserDetailsArgs) => {
  return withSupabase((supabase) => supabase.schema('private').rpc('get_user_info', { input: data }));
};

export type GetUserDetailsResponse = Awaited<ReturnType<typeof useGetUserDetails>>;
