import { type MuteChatArgs, useMuteChatFunc } from '~/composables/supabase/useMuteChat';

export const useMuteChat = defineMutation(() => {
  const { mutateAsync: muteChat, asyncStatus } = useMutation({
    mutation: (data: MuteChatArgs) => useMuteChatFunc(data),
    onSuccess: (response) => {
      if (response.error) {
        console.error('Failed to mute chat:', response.error);
        throw new Error('Failed to mute chat');
      }
    },
    onError: (err) => {
      showToastError(err);
    },
  });

  return {
    muteChat,
    isMutingChat: computed(() => asyncStatus.value === 'loading'),
  };
});
