<template>
  <ContextMenu v-if="isMobile" v-model:open="open" :modal="false" @update:open="open = $event">
    <ContextMenuTrigger as-child>
      <a
        :href="seg.href"
        :target="seg.kind === 'url' ? '_blank' : undefined"
        :rel="seg.kind === 'url' ? 'noopener noreferrer' : undefined"
        :class="
          cn('underline underline-offset-2 hover:opacity-80 rounded-sm', linkColorClass, open && linkActiveBgClass)
        "
        draggable="false"
        style="-webkit-touch-callout: none; -webkit-user-select: none; -webkit-user-drag: none"
        @click.stop="(e) => onLinkClick(e, seg)"
        @dragstart.prevent
        >{{ seg.value }}</a
      >
    </ContextMenuTrigger>
    <ContextMenuContent
      @pointer-down-outside="open = false"
      @focus-outside="open = false"
      @interact-outside="open = false"
    >
      <ContextMenuItem v-if="seg.kind === 'url'" @select="openLinkInBrowser(seg)">
        <ExternalLinkIcon class="w-4 h-4 mr-2" /> Open in browser
      </ContextMenuItem>
      <ContextMenuItem @select="copyLink(seg)">
        <CopyIcon class="w-4 h-4 mr-2" /> Copy {{ seg.kind === 'email' ? 'email' : 'link' }}
      </ContextMenuItem>
    </ContextMenuContent>
  </ContextMenu>
  <a
    v-else
    :href="seg.href"
    :target="seg.kind === 'url' ? '_blank' : undefined"
    :rel="seg.kind === 'url' ? 'noopener noreferrer' : undefined"
    :class="cn('underline underline-offset-2 hover:opacity-80', linkColorClass)"
    @click.stop="(e) => onLinkClick(e, seg)"
    >{{ seg.value }}</a
  >
</template>

<script setup lang="ts">
import { Browser } from '@capacitor/browser';
import { CopyIcon, ExternalLinkIcon } from 'lucide-vue-next';
import { ContextMenu, ContextMenuContent, ContextMenuItem, ContextMenuTrigger } from '~/components/ui/context-menu';
import { cn } from '@/lib/utils';
import type { LinkifiedSegment } from '@/utils/linkifyTokens';

type LinkSegment = Extract<LinkifiedSegment, { type: 'link' }>;

interface Props {
  seg: LinkSegment;
  linkColorClass: string;
  linkActiveBgClass: string;
  isMobile: boolean;
}

const props = defineProps<Props>();

const open = ref(false);

watch(open, (isOpen, wasOpen) => {
  if (isOpen && !wasOpen) linkMenuOpenCount.value++;
  else if (!isOpen && wasOpen) linkMenuOpenCount.value = Math.max(0, linkMenuOpenCount.value - 1);
});

// Radix can unmount the trigger while the menu is still open (e.g. virtual list recycle);
// the watcher above won't fire in that case, so we also clean up here.
onBeforeUnmount(() => {
  if (open.value) linkMenuOpenCount.value = Math.max(0, linkMenuOpenCount.value - 1);
});

watch(
  () => linkMenuCloseSignal.value,
  () => {
    if (!open.value) return;
    document.body.dispatchEvent(
      new PointerEvent('pointerdown', {
        bubbles: true,
        cancelable: true,
        pointerType: 'mouse',
        clientX: 0,
        clientY: 0,
      })
    );
  },
  { flush: 'sync' }
);

async function openLinkInBrowser(seg: LinkSegment) {
  if (seg.kind !== 'url') return;
  try {
    await Browser.open({ url: seg.href });
  } catch (err) {
    showToastError('Failed to open link');
    captureExceptionToSentry(new Error('Failed to open link: ' + err));
  }
}

async function onLinkClick(e: MouseEvent, seg: LinkSegment) {
  if (seg.kind !== 'url') return;
  if (!props.isMobile) return;
  e.preventDefault();
  try {
    await Browser.open({ url: seg.href });
  } catch (err) {
    showToastError('Failed to open link');
    captureExceptionToSentry(new Error('Failed to open link: ' + err));
  }
}

async function copyLink(seg: LinkSegment) {
  try {
    await navigator.clipboard.writeText(seg.href);
  } catch (err) {
    showToastError('Failed to copy link');
    captureExceptionToSentry(new Error('Failed to copy link: ' + err));
  }
}
</script>
