import { withCachedSupabase } from './useCheckSupabaseClient';

interface CreatePublicLinkForAttachmentArgs {
  path: string;
  time: number | null;
}

export const useCreatePublicLinkForAttachmentFunc = async (data: CreatePublicLinkForAttachmentArgs) => {
  return withCachedSupabase(`attachment_public_link:${data.path}`, (supabase) =>
    supabase.storage.from('attachments').createSignedUrl(data.path, data.time ?? 60)
  );
};

export type CreatePublicLinkForAttachmentResponse = Awaited<ReturnType<typeof useCreatePublicLinkForAttachmentFunc>>;
