import { useSendMessageFunc, type SendMessageArgs } from '~/composables/supabase/useSendMessage';

export const useSendMessage = defineMutation(() => {
  const { mutateAsync: sendMessage, asyncStatus } = useMutation({
    mutation: (data: { data: SendMessageArgs }) => useSendMessageFunc(data.data),
    onSuccess: (response, params) => {
      if (response.error) {
        throw new Error('Failed to send message');
      }
    },
    onError: (err) => {
      showToastError(err);
    },
  });

  return {
    sendMessage,
    isSendingMessage: computed(() => asyncStatus.value === 'loading'),
  };
});
