<template>
  <ChatAttachmentDialog
    :name="attachment.name"
    :path="attachment.path"
    :type="attachment.mime"
    :size="attachment.size"
    :public-link="previewUrl"
    :extension="attachment.mime?.includes('image/') ? null : fileExtension"
    :download-enabled="downloadEnabled"
  >
    <img
      v-if="attachment.mime?.includes('image/') && previewUrl"
      :src="previewUrl"
      alt="attachment-preview"
      class="w-full h-full object-cover"
    />

    <div
      v-else
      class="flex flex-col gap-1 items-center justify-center rounded-md border h-full p-1 bg-accent text-slate-600"
    >
      <div class="relative">
        <span
          class="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/3 text-xs pointer-events-none"
          >{{ fileExtension }}</span
        >
        <FileIcon class="w-11 h-11 stroke-slate-400" />
      </div>
      <span class="text-xs text-slate-600 line-clamp-2 max-w-full" :title="attachment.name">{{
        attachment.name.replace(/\.[^/.]+$/, '')
      }}</span>
    </div>
  </ChatAttachmentDialog>
</template>

<script setup lang="ts">
import { FileIcon } from 'lucide-vue-next';
interface Props {
  attachment: PendingAttachment;
  previewUrl?: string | null;
  fileExtension: string;
  downloadEnabled: boolean;
}

withDefaults(defineProps<Props>(), {
  previewUrl: null,
  downloadEnabled: false,
});
</script>
