<template>
  <Dialog v-model:open="model">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="rounded-lg max-w-xs sm:max-w-md gap-6">
      <AppLoader v-if="isGettingChannelDetails" variant="table" subject="channel details" class="!pb-0" />
      <AppError
        v-else-if="channelDetails?.error"
        variant="table"
        title="Failed to load channel details"
        action-text=""
      />
      <AppEmpty v-else-if="!data" variant="table" subject="channel details" />
      <template v-else-if="data">
        <DialogHeader class="gap-y-2">
          <AvatarImageWrapper :src="''" alt="ProfilePic" :fallback="avatarFallback" size="lg" class="mx-auto" />
        </DialogHeader>
        <div :class="cn('flex flex-col gap-4', { 'items-center': isAdmin, 'items-end': isManagerOrAnyCanvasser })">
          <DialogTitle class="text-xl">{{ data?.title }}</DialogTitle>
          <div class="flex flex-col gap-2 w-full">
            <LabeledValueIcon label="Project Type" :icon="BriefcaseIcon">
              <span class="lowercase first-letter:uppercase">{{ data.type }}</span>
            </LabeledValueIcon>
            <LabeledValueIcon label="Participants" :icon="UsersRoundIcon">
              {{ data.participant_count }}
            </LabeledValueIcon>
          </div>
        </div>
        <DialogFooter v-if="data?.project_id">
          <NuxtLink :to="{ name: 'projects-id', params: { id: data.project_id } }">
            <Button :prepend-icon="InfoIcon" variant="outline">Details</Button>
          </NuxtLink>
          <NuxtLink v-if="isAdmin" :to="{ name: 'projects-id-assignments', params: { id: data.project_id } }">
            <Button :prepend-icon="BookUserIcon" variant="outline">Assignments</Button>
          </NuxtLink>
        </DialogFooter>
      </template>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { BookUserIcon, BriefcaseIcon, InfoIcon, UsersRoundIcon } from 'lucide-vue-next';
import { useGetChannelDetails } from '~/composables/supabase/useGetChannelDetails';
import { cn } from '@/lib/utils';

const model = defineModel<boolean>('open', { default: false });

const { isAdmin, isManagerOrAnyCanvasser } = useUserRole();

interface Props {
  id: string | null;
}

const props = defineProps<Props>();

const { data: channelDetails, isLoading: isGettingChannelDetails } = useQuery({
  key: () => ['channel.info', props.id],
  query: () => useGetChannelDetails({ chat_id: props.id }),
  enabled: () => !!props.id && !!model.value,
});

const data = computed(() => channelDetails.value?.data || null);
const avatarFallback = computed(() => getAvatarFallback(data.value?.title));
</script>
