<template>
  <div class="flex flex-col gap-2 bg-gray-50 border-t">
    <div v-if="uploadedFiles.length > 0" class="flex gap-2 items-center overflow-x-auto px-12 pt-2">
      <ChatAttachmentItem
        v-for="file in uploadedFiles"
        :key="file.data.id"
        :attachment="file.data"
        :upload-status="file.status"
        :upload-error="file.error"
        :preview-url="file.previewUrl"
        :file="file.file"
        :is-removable="!loading"
        enable-retry
        @remove="removeAttachment"
        @retry="retryUpload"
      />
    </div>
    <div class="flex flex-col">
      <div v-if="messageToReply" class="flex gap-2 px-2">
        <div class="min-w-9" />
        <div class="w-full border border-b-0 rounded-t-md p-2 flex gap-2 items-start justify-between bg-secondary">
          <p v-if="messageToReply?.body" class="line-clamp-1 w-full text-sm">| {{ messageToReply?.body }}</p>
          <div
            v-else-if="Array.isArray(messageToReply?.attachments) && messageToReply?.attachments.length"
            class="flex gap-2 overflow-x-auto"
          >
            <template v-for="attachment in messageToReply?.attachments">
              <ChatAttachmentItem
                v-if="isAttachment(attachment)"
                :key="(attachment as any).id"
                :attachment="attachment"
                enable-download
                upload-status="success"
                class="shrink-0"
              />
            </template>
          </div>
          <XIcon v-if="!loading" class="cursor-pointer min-h-4 max-h-4 min-w-4 max-w-4" @click="onCancelReply" />
        </div>
        <div class="min-w-9" />
      </div>
      <div class="flex items-end gap-2 p-2">
        <input ref="filesEl" type="file" class="hidden" multiple :accept="accept" @change="onFilesSelected" />

        <div class="h-10 flex items-center">
          <Button
            variant="outline"
            size="icon"
            class="rounded-full"
            title="Attach files"
            :disabled="loading || isUploading"
            @click="filesEl?.click()"
          >
            <PaperclipIcon />
          </Button>
        </div>

        <div class="flex-1 relative">
          <Textarea
            id="inputField"
            ref="inputField"
            v-model="input"
            rows="1"
            class="w-full min-h-0 pr-6 resize-none overflow-y-auto leading-5 focus-visible:ring focus-visible:ring-offset-0 focus-visible:ring-black"
            @update:model-value="autoResize"
            @keydown.enter.exact="onEnterKey"
            @keydown.esc.exact.prevent="messageToEdit ? onCancelEdit() : null"
            @vue:mounted="
              () => {
                autoResize();
              }
            "
          />
          <!-- <span class="absolute right-2 top-1/2 -translate-y-1/2">
            <InfoIcon class="h-4 w-4" />
          </span> -->
        </div>
        <div class="h-10 flex items-center">
          <ChatsInputsEditControls
            v-if="messageToEdit"
            :is-edit-loading="isEditingMessage"
            @confirm="onConfirmEdit"
            @cancel="onCancelEdit"
            @vue:mounted="onEditMessageTrigger"
          />
          <div v-else class="h-9 w-9 flex justify-center items-center">
            <Spinner v-if="loading" class="h-7 w-7" />
            <SendIcon
              v-else
              :class="
                cn('text-muted-foreground w-7 h-7', {
                  'cursor-pointer text-foreground': input.trim() || uploadedFiles.length > 0,
                })
              "
              :disabled="loading || isUploading || (!input?.trim() && uploadedFiles.length === 0)"
              @click.prevent.stop="handleSend"
            />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { PaperclipIcon, SendIcon, XIcon, InfoIcon } from 'lucide-vue-next';
import { Capacitor } from '@capacitor/core';
import { Spinner } from '~/assets/icons';
import { cn } from '@/lib/utils';
import type { SendMessageArgs } from '~/composables/supabase/useSendMessage';
import { useUploadFileSupabase } from '~/mutations/chats/uploadFile';
import { processFileData } from '~/utils/chats/processFiles';
import type { UploadItem } from '~/types/attachments';
import { uploadStatuses } from '~/constants/chats/attachments';
import type { ChatMessage } from '~/composables/supabase/useChatMessages';
import { useEditMessage } from '~/mutations/chats/editMessage';

interface Props {
  loading?: boolean;
  chatId?: string | null;
  bucket?: string;
  accept?: string;
  messageToEdit?: ChatMessage | null;
  messageToReply?: ChatMessage | null;
}

const props = withDefaults(defineProps<Props>(), {
  loading: false,
  bucket: 'attachments',
  accept: '',
  chatId: null,
  messageToEdit: null,
  messageToReply: null,
});

interface Emits {
  (e: 'send', data: SendMessageArgs): void;

  (e: 'cancelEdit'): void;

  (e: 'confirmEdit'): void;

  (e: 'cancelReply'): void;
}

const emit = defineEmits<Emits>();

const filesEl = useTemplateRef('filesEl');
const inputField = useTemplateRef('inputField');

const input = defineModel<string>('inputText', { default: '' });

const uploadedFiles = defineModel<UploadItem[]>('files', { default: [] });

const groupId = defineModel<string | null>('group', { default: null });
const isUploading = ref(false);

const messageLimit = 4000;

const isCloseToLimit = computed(() => input.value?.trim().length >= messageLimit - 200);

const { uploadFile } = useUploadFileSupabase();

function createUploadTasks(items: UploadItem[]) {
  return items.map((item) => {
    item.status = uploadStatuses.uploading;
    item.error = servingOffline.value ? 'Cannot upload file while offline' : null;
    if (servingOffline.value) return Promise.reject({ error: { message: 'Cannot upload file while offline' } });
    return uploadFile({ file: item.file, path: item.data!.path });
  });
}

async function uploadAllFiles(items: UploadItem[]) {
  isUploading.value = true;

  const tasks = createUploadTasks(items);
  const results = await Promise.allSettled(tasks);

  results.forEach((result, index) => {
    const item = items[index];

    if (result.status === 'fulfilled') {
      if ((result.value as any)?.error) {
        item.status = uploadStatuses.error;
        item.error = (result.value as any).error.message ?? 'Upload failed';
      } else {
        item.status = uploadStatuses.success;
      }
    } else {
      item.status = uploadStatuses.error;
      item.error = result.reason?.message ?? 'Upload failed';
      captureExceptionToSentry(new Error('File upload failed: ' + item.file.name + ' - ' + item.error));
    }
  });

  isUploading.value = false;
}

async function retryUpload(id: string) {
  const item = uploadedFiles.value.find((file) => file.data.id === id);
  if (!item) return;
  await uploadAllFiles([item]);
}

const hasUploading = computed(() => uploadedFiles.value.some((f) => f.status === uploadStatuses.uploading));

const hasErrors = computed(() => uploadedFiles.value.some((f) => f.status === uploadStatuses.error));

async function onFilesSelected(event: Event) {
  if (servingOffline.value) {
    if (filesEl.value) filesEl.value.value = '';
    showOfflineToastError();
    return;
  }
  const inputEl = event.target as HTMLInputElement;
  const files = inputEl.files ? Array.from(inputEl.files) : [];

  if (!files.length) return;

  try {
    const { userId } = useUserRole();
    if (!userId.value) throw new Error('Not authenticated');

    isUploading.value = true;
    const chatId = props.chatId;
    const userIdTyped = userId.value;

    let gid = groupId.value;

    if (!gid) {
      gid = crypto.randomUUID();
      groupId.value = gid;
    }

    const items: UploadItem[] = files.map((file) => {
      const id = crypto.randomUUID();
      return {
        file,
        previewUrl: URL.createObjectURL(file),
        data: processFileData({
          file,
          chatId,
          userId: userIdTyped,
          groupId: gid,
          bucket: props.bucket!,
          attachmentId: id,
        }),
        status: uploadStatuses.queued,
        error: null,
      };
    });

    uploadedFiles.value.push(...items);

    await uploadAllFiles(items);
  } catch (e) {
    console.error(e);
  } finally {
    isUploading.value = false;
  }
}

//TODO: mb refactor this to make messages be added to chat on client side and skip new_messages event from realtime it sender_id us logged in user
async function handleSend() {
  if (isUploading.value) {
    showToastError(
      'Please wait for all files to finish uploading before sending the message.',
      'Unable to send message'
    );
    return;
  }
  if (hasUploading.value) {
    showToastError(
      'Please wait for all files to finish uploading before sending the message.',
      'Unable to send message'
    );
    return;
  }
  if (hasErrors.value) {
    showToastError(
      'Some attachments failed to upload. Please try to re-upload or reattach them.',
      'Unable to send message'
    );
    return;
  }

  const message = input.value.trim();
  if (!message && uploadedFiles.value.length === 0) return;

  if (message.length > messageLimit) {
    showToastError(
      `Message cannot exceed ${messageLimit} characters. Your message is ${message.length} characters long.`,
      'Unable to send message'
    );
    return;
  }

  try {
    const payload: SendMessageArgs = {
      chat_id: props.chatId,
      body: message,
      reply_to_message_id: props.messageToReply?.id || null,
      forwarded_from_user_id: null,
      attachment_group_id: groupId.value,
      dedup_key: null,
    };

    emit('send', payload);
  } catch (err) {
    console.error(err);
  } finally {
    inputField.value?.$el.focus();
  }
}

function removeAttachment(id: string) {
  uploadedFiles.value = uploadedFiles.value.filter((file) => file.data.id !== id);
}

watch(
  //TODO replace with better approach. Done cause modeleValue changes with delay
  () => uploadedFiles.value.length,
  (newValue, oldValue) => {
    if (newValue === 0 && oldValue) {
      groupId.value = null;
      if (filesEl.value) filesEl.value.value = '';
    }
  }
);

watch(
  //TODO replace with better approach.
  () => input.value,
  async (newValue, oldValue) => {
    await nextTick();
    if (oldValue && !newValue) autoResize();
  }
);

function autoResize() {
  const el = inputField.value?.$el as HTMLTextAreaElement;
  if (!el) return;

  el.style.height = 'auto';

  const lineHeight = 20;
  const maxHeight = lineHeight * 5;

  el.style.height = Math.min(el.scrollHeight, maxHeight) + 4 + 'px';
}

const { editMessage, isEditingMessage } = useEditMessage();

async function onConfirmEdit() {
  if (!props.messageToEdit) {
    showToastError('', 'Unable to edit message');
    return;
  }
  if (!props.messageToEdit?.attachment_group_id && !input.value.trim()) {
    showToastError('Message cannot be empty.', 'Unable to edit message');
    return;
  }
  if (props.messageToEdit.body === input.value) {
    onCancelEdit();
    return;
  }
  const message = input.value.trim();

  if (message.length > messageLimit) {
    showToastError(
      `Message cannot exceed ${messageLimit} characters. Your message is ${message.length} characters long.`,
      'Unable to send message'
    );
    return;
  }

  await editMessage({ input: { message_id: props.messageToEdit.id, new_body: message } }).then(() => {
    input.value = '';
    emit('confirmEdit');
  });
}

function onCancelEdit() {
  input.value = '';
  emit('cancelEdit');
}

function onEditMessageTrigger() {
  if (props.messageToEdit) {
    input.value = props.messageToEdit?.body || '';
    inputField.value?.$el.focus();
  }
}

function onCancelReply() {
  emit('cancelReply');
}

function onEnterKey(event: KeyboardEvent) {
  if (Capacitor.isNativePlatform()) return;
  if (event.isComposing) return;
  if (window.matchMedia('(pointer: coarse)').matches) return;
  event.preventDefault();
  if (props.messageToEdit) onConfirmEdit();
  else handleSend();
}

function isAttachment(attachment: unknown): attachment is PendingAttachment {
  return typeof attachment === 'object' && attachment !== null && 'id' in attachment && 'path' in attachment;
}
</script>
