import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

export type EditMessageArgs = Database['private']['Functions']['edit_message']['Args'];

export const useEditMessageFunc = async (data: EditMessageArgs) => {
  return withSupabase((supabase) => supabase.rpc('edit_message', data));
};

export type GetMessagesResponse = Awaited<ReturnType<typeof useEditMessageFunc>>;
