// Cross-component coordination for per-link context menus in chat messages.
//
// Contract:
// - Each `ChatsLinkifiedTextLink` increments `linkMenuOpenCount` while its menu is open
//   (and decrements on close/unmount). `isAnyLinkMenuOpen` is the aggregate flag the
//   message list uses to mount its tap-absorbing overlay.
// - When the message-level context menu opens, the page bumps `linkMenuCloseSignal`
//   to broadcast "close any open link menus". Each link menu watches this signal
//   synchronously and dispatches a body `pointerdown`, which Radix treats as an
//   outside-pointerdown and closes the menu — sidestepping the lack of a public
//   imperative close API.
//
// Caveat: this is module-level singleton state, so all link menus on the page (and
// any future parallel chat surfaces) coordinate on the same counter.
export const linkMenuCloseSignal = ref(0);

export const linkMenuOpenCount = ref(0);

export const isAnyLinkMenuOpen = computed(() => linkMenuOpenCount.value > 0);
