<template>
  <div class="min-h-16 w-full p-2 grid grid-cols-8">
    <div class="flex items-center">
      <NuxtLink :to="{ name: 'chats', query: { ...useRoute().query } }">
        <Button variant="ghost" size="icon" class="rounded-full"><ArrowLeftIcon /></Button>
      </NuxtLink>
    </div>
    <div v-if="loading" class="col-span-6 flex justify-center items-center">
      <Skeleton class="w-full h-10" />
    </div>
    <component
      :is="chatWithGrace ? ChatGraceInfoModal : data.type === 'CHANNEL' ? ChatChannelInfoModal : ChatUserInfoModal"
      v-else-if="data"
      :id="data.id"
      class="col-span-6"
    >
      <div :class="cn('col-span-6 flex justify-center items-center gap-2 cursor-pointer')">
        <ChatsUserAvatar :avatar-url="data.avatarUrl" :name="data.title" size="sm" />
        <SparklesIcon v-if="chatWithGrace" class="size-5 text-yellow-500 animate-pulse inline-block" />
        <div class="flex flex-col">
          <div class="flex items-center gap-2">
            <span
              :class="
                cn('font-medium line-clamp-2', {
                  'line-clamp-2': data.type !== 'DM',
                  'line-clamp-1': data.type === 'DM',
                })
              "
              >{{ data?.title }}</span
            >
            <VolumeOffIcon v-if="props.muted" class="w-4 h-4 shrink-0 text-muted-foreground" />
          </div>
          <span v-if="subtitle" class="text-muted-foreground text-sm">{{ subtitle }}</span>
        </div>
      </div>
    </component>
    <div v-if="route.name === 'chats-id'" class="flex items-center justify-end">
      <DropdownMenu :modal="false">
        <DropdownMenuTrigger
          ><Button variant="ghost" size="icon" class="rounded-full"><EllipsisVerticalIcon /></Button
        ></DropdownMenuTrigger>
        <DropdownMenuContent>
          <DropdownMenuItem :disabled="isMutingChat" :loading="isMutingChat" @click="onMuteClick"
            ><component :is="props.muted ? VolumeOffIcon : Volume2Icon" />
            {{ props.muted ? 'Unmute' : 'Mute' }}</DropdownMenuItem
          >
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ArrowLeftIcon, EllipsisVerticalIcon, SparklesIcon, Volume2Icon, VolumeOffIcon } from 'lucide-vue-next';
import { type ChatParticipant } from '~/composables/supabase/useGetChatParticipants';
import type { ChatType, GetChatInfoResponse } from '~/composables/supabase/useChatInfo';
import ChatChannelInfoModal from '~/components/chats/ChatChannelInfoModal.vue';
import ChatUserInfoModal from './ChatUserInfoModal.vue';
import ChatGraceInfoModal from './ChatGraceInfoModal.vue';
import { useMuteChat } from '~/mutations/chats/muteChat';
import { cn } from '@/lib/utils';
import { GRACE_ID } from '~/constants/chats/graceId';

interface Props {
  data?: {
    title: string;
    avatarUrl: string | null;
    role: ChatParticipant['role'] | null;
    type: ChatType | null;
    id: string;
  } | null;
  loading: boolean;
  muted?: boolean;
}

const props = defineProps<Props>();

const route = useRoute();

const subtitle = computed(() => {
  if (props.data?.role && !chatWithGrace.value) return props.data?.role?.replaceAll('_', ' ').toLowerCase();
  return null;
});

const chatWithGrace = computed(() => props.data?.id === GRACE_ID && props.data?.type === 'DM');

const { muteChat, isMutingChat } = useMuteChat();

async function onMuteClick() {
  if (route.name !== 'chats-id') {
    showToastError('Unable to mute/unmute this chat');
    return;
  }
  const chatId = route.params.id;
  await muteChat({ chat_id: chatId }).then((response) => {
    const queryCache = useQueryCache();
    queryCache.setQueryData<GetChatInfoResponse | undefined>(['chatInfo.id', chatId], (prevData) => {
      if (!prevData?.data) return prevData;

      return {
        ...prevData,
        data: {
          ...prevData.data,
          muted_until: props.muted ? null : response.data,
        },
      };
    });
  });
}
</script>
