<template>
  <Dialog v-model:open="model">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="rounded-lg max-w-xs sm:max-w-md gap-6">
      <AppLoader v-if="isGettingUserDetails" variant="table" subject="user details" class="!pb-0" />
      <AppError v-else-if="userDetails?.error" variant="table" action-text="" title="Failed to load user details" />
      <AppEmpty v-else-if="!data" variant="table" subject="user details" />
      <template v-else-if="data">
        <DialogHeader class="gap-y-2">
          <ChatsUserAvatar :avatar-url="data.avatar_url" :name="data.display_name" size="lg" class="mx-auto" />
        </DialogHeader>
        <div class="flex flex-col items-center gap-4">
          <DialogTitle class="text-xl">{{ data.display_name }}</DialogTitle>
          <div class="flex flex-col gap-2 w-full">
            <LabeledValueIcon label="Role" :icon="UserIcon">
              <span class="lowercase first-letter:uppercase">{{ data.role.replaceAll('_', ' ') }}</span>
            </LabeledValueIcon>
            <LabeledValueIcon label="Phone" :icon="PhoneIcon">
              {{ data.phone_number }}
            </LabeledValueIcon>
            <LabeledValueIcon label="Email" :icon="AtSignIcon">
              <span class="whitespace-pre-wrap [overflow-wrap:anywhere]"> {{ data.email }}</span>
            </LabeledValueIcon>
          </div>
        </div>
        <DialogFooter>
          <NuxtLink v-if="isAdmin" :to="{ name: 'users-id', params: { id: data.id } }">
            <Button :prepend-icon="InfoIcon" variant="outline">Details</Button>
          </NuxtLink>
        </DialogFooter>
      </template>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { AtSignIcon, InfoIcon, PhoneIcon, UserIcon } from 'lucide-vue-next';
import { useGetUserDetails } from '~/composables/supabase/useGetUserDetails';
//TODO: mb merge with ChatChannelInfoModal.vue

const model = defineModel<boolean>('open', { default: false });

const { isAdmin } = useUserRole();

interface Props {
  id: string | null;
}

const props = defineProps<Props>();

const { data: userDetails, isLoading: isGettingUserDetails } = useQuery({
  key: () => ['user.info', props.id],
  query: () => useGetUserDetails({ user_id: props.id }),
  enabled: () => !!props.id && !!model.value,
});

const data = computed(() => userDetails.value?.data || null);
</script>
