import { type EditMessageArgs, useEditMessageFunc } from '~/composables/supabase/useEditMessage';

export const useEditMessage = defineMutation(() => {
  const { mutateAsync: editMessage, asyncStatus } = useMutation({
    mutation: (data: EditMessageArgs) => useEditMessageFunc(data),
    onSuccess: (response) => {
      if (response.error) {
        console.error('Failed to edit message:', response.error);
        throw new Error('Failed to edit message');
      }
    },
    onError: (err) => {
      showToastError(err);
    },
  });

  return {
    editMessage,
    isEditingMessage: computed(() => asyncStatus.value === 'loading'),
  };
});
