import { useUploadFileFunc } from '~/composables/supabase/uploadFile';

export const useUploadFileSupabase = defineMutation(() => {
  const { mutateAsync: uploadFile, asyncStatus } = useMutation({
    mutation: ({ file, path }: { file: File; path: string }) => {
      return useUploadFileFunc(path, file);
    },
    onSuccess: (response) => {
      if (response.error) {
        console.error('Failed to upload file:', response.error);
        throw new Error('Failed to upload file');
      }
    },
    onError: (err) => {
      showToastError(err);
    },
  });

  return {
    uploadFile,
    isUploadingFile: computed(() => asyncStatus.value === 'loading'),
  };
});
