import { useUploadAttachmentsFunc, type UploadAttachmentsArgs } from '~/composables/supabase/uploadAttachments';

export const useUploadAttachments = defineMutation(() => {
  const { mutateAsync: uploadAttachments, asyncStatus } = useMutation({
    mutation: (args: UploadAttachmentsArgs) => useUploadAttachmentsFunc(args),
    onSuccess: (response) => {
      if (response.error) {
        console.error('Failed to upload attachments:', response.error);
        throw new Error('Failed to upload attachments');
      }
    },
    onError: (err) => {
      showToastError(err);
    },
  });

  return {
    uploadAttachments,
    isUploadingAttachments: computed(() => asyncStatus.value === 'loading'),
  };
});
