<template>
  <Dialog v-model:open="model" @update:open="onModelUpdate">
    <DialogTrigger as-child @click="onClick">
      <slot />
    </DialogTrigger>
    <DialogContent class="rounded-lg max-w-sm sm:max-w-xl gap-6">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl break-all">{{ name }}</DialogTitle>
        <DialogDescription />
      </DialogHeader>
      <div class="flex flex-col gap-3">
        <div v-if="type?.includes('image')" class="aspect-w-16 aspect-h-9">
          <AppLoader v-if="isImageLoading" variant="inline" subject="image" />
          <AppError
            v-else-if="loadedPublicLinkError"
            title="Failed to load image"
            message=""
            variant="table"
            action-text=""
          />
          <AppEmpty v-else-if="!loadedPublicLink" subject="image" variant="table" />
          <img
            :src="loadedPublicLink"
            alt="Attachment"
            :class="cn('w-full h-full', { hidden: isImageLoading || !loadedPublicLink })"
            @load="isImageLoading = false"
          />
        </div>
        <div v-else class="flex justify-center items-center relative">
          <span
            class="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/3 text-[clamp(16px,_calc(1rem_+_2vw),_36px)] pointer-events-none"
            >{{ extension }}</span
          >
          <FileIcon class="aspect-w-9 aspect-h-16 w-2/3 h-2/3" />
        </div>
      </div>
      <DialogFooter>
        <div class="flex flex-wrap justify-end gap-2">
          <Button
            v-if="downloadEnabled"
            class="h-10 px-4"
            :disabled="size === 0"
            :prepend-icon="DownloadIcon"
            @click="downloadFile"
          >
            {{ formatBytes(props.size) }}
          </Button>
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { useCreatePublicLinkForAttachmentFunc } from '~/composables/supabase/createPublicLinkForAttachment';
import { DownloadIcon, FileIcon } from 'lucide-vue-next';
import { cn } from '@/lib/utils';

interface Props {
  path: string;
  name: string;
  type: string | null;
  size: number;
  publicLink?: string | null;
  extension?: string | null;
  downloadEnabled?: boolean;
}

const props = defineProps<Props>();

const model = defineModel<boolean>('open', { default: false });
const emit = defineEmits(['click']);

const loadedPublicLink = ref<string>(props.publicLink || '');
const loadedPublicLinkError = ref<string | null>(null);
const isImageLoading = ref<boolean>(false);

async function onModelUpdate(value: boolean) {
  if (value && !props.publicLink) {
    if (props.type?.includes('image')) {
      isImageLoading.value = true;
      await useCreatePublicLinkForAttachmentFunc({ path: props.path, time: 120 })
        .then((response) => {
          if (response.error) {
            loadedPublicLinkError.value = response.error.message;
          } else {
            loadedPublicLink.value = response.data.signedUrl;
          }
        })
        .catch((err) => {
          console.error('Failed to load public link', err);
          loadedPublicLinkError.value = 'Failed to load public link';
          captureExceptionToSentry(new Error('Failed to load public link for attachment: ' + err));
          isImageLoading.value = false;
        });
    }
  }
}

async function downloadFile() {
  await useCreatePublicLinkForAttachmentFunc({ path: props.path, time: 60 }).then((response) => {
    if (response.error) {
      showToastError('Failed to download file');
      captureExceptionToSentry(new Error('Failed to download file: ' + response.error.message));
      return;
    } else {
      try {
        const downloadUrl = new URL(response.data.signedUrl);
        downloadUrl.searchParams.append('download', props.path.split('/').pop() || '');

        const link = document.createElement('a');
        link.href = downloadUrl.toString();
        link.download = props.path.split('/').pop() || '';
        document.body.appendChild(link);
        console.log(downloadUrl);
        link.click();
        document.body.removeChild(link);
        model.value = false;
      } catch (err) {
        console.error('Failed to download file', err);
        showToastError('Failed to download file');
        captureExceptionToSentry(new Error('Failed to download file: ' + err));
      }
    }
  });
}

type Unit = 'b' | 'kb' | 'mb' | 'gb';

const UNITS: Array<{ unit: Unit; size: number }> = [
  { unit: 'gb', size: 1024 ** 3 },
  { unit: 'mb', size: 1024 ** 2 },
  { unit: 'kb', size: 1024 },
  { unit: 'b', size: 1 },
];

function formatBytes(bytes: number, decimals = 1): string {
  if (!Number.isFinite(bytes) || bytes < 0) {
    console.error('bytes must be a non-negative number');
    return '0b';
  }

  for (const { unit, size } of UNITS) {
    if (bytes >= size) {
      const value = bytes / size;
      return `${value.toFixed(decimals)}${unit}`;
    }
  }

  return `0b`;
}

function onClick(e: MouseEvent) {
  e.stopPropagation();
  emit('click', e);
}
</script>
