import { find } from 'linkifyjs';

export type LinkifiedSegment =
  | { type: 'text'; value: string }
  | { type: 'link'; value: string; href: string; kind: 'url' | 'email' };

/**
 * Splits a chat message body into a contiguous segment array of plain-text
 * gaps and detected URL / email links. Returns `[]` for null / undefined /
 * empty / whitespace-only input.
 */
export function linkifyTokens(text: string | null | undefined): LinkifiedSegment[] {
  if (!text || !text.trim()) return [];

  // `defaultProtocol: 'https'` makes hrefs for bare `www.x.com` resolve to
  // `https://www.x.com` while leaving `value` (display text) untouched.
  const matches = find(text, { defaultProtocol: 'https' });

  const segments: LinkifiedSegment[] = [];
  let cursor = 0;

  for (const match of matches) {
    if (match.type !== 'url' && match.type !== 'email') continue;
    if (match.start > cursor) {
      segments.push({ type: 'text', value: text.slice(cursor, match.start) });
    }
    segments.push({
      type: 'link',
      value: match.value,
      href: match.href,
      kind: match.type === 'email' ? 'email' : 'url',
    });
    cursor = match.end;
  }

  if (cursor < text.length) {
    segments.push({ type: 'text', value: text.slice(cursor) });
  }

  return segments;
}
